    { key: "body", name: "Pump housing", geometry: new CylinderGeometry(0.56, 0.56, 0.72, 28), position: [0.25, 0.8, 0], offset: [0, 0.18, 0], color: "#43b9a1", rotation: horizontal },
    { key: "rotor", name: "Impeller", geometry: new TorusGeometry(0.27, 0.095, 8, 16), position: [0.64, 0.8, 0], offset: [0.75, 0.18, 0], color: "#e8b86b", rotation: new Quaternion().setFromAxisAngle(new Vector3(0, 1, 0), Math.PI / 2) },
    { key: "cover", name: "Service cover", geometry: new CylinderGeometry(0.57, 0.57, 0.09, 28), position: [0.71, 0.8, 0], offset: [1.4, 0.18, 0], color: "#7893a8", rotation: horizontal },
    { key: "outlet", name: "Outlet", geometry: new CylinderGeometry(0.18, 0.18, 0.6, 16), position: [0.25, 1.5, 0], offset: [0, 0.9, 0], color: "#43b9a1" },
    { key: "foot-a", name: "Motor mount", geometry: new BoxGeometry(0.75, 0.24, 0.9), position: [-0.85, 0.32, 0], offset: [-0.65, 0, 0], color: "#597488" },
    { key: "foot-b", name: "Pump mount", geometry: new BoxGeometry(0.62, 0.25, 1), position: [0.25, 0.33, 0], offset: [0, 0, 0], color: "#597488" }
