function makeDemoDocument(assets, stress = false) {
  const pump = assets.find((asset) => asset.assetId === "p0-pump");
  const valve = assets.find((asset) => asset.assetId === "p0-valve");
  const entities = [];
  const count = stress ? 1e3 : 4;
  for (let index2 = 0; index2 < count; index2++) {
    const asset = stress || index2 === 3 ? valve : pump;
    const id = `device-${String(index2 + 1).padStart(4, "0")}`;
    entities.push({
      entityId: id,
      name: `${stress || index2 === 3 ? "Valve" : "Pump"} ${index2 + 1}`,
      kind: "model",
      businessId: id,
      parentId: null,
      assetRef: { assetId: asset.assetId, assetRevision: asset.assetRevision },
      transform: {
        position: stress ? [(index2 % 32 - 16) * 2.2, 0, (Math.floor(index2 / 32) - 16) * 2.2] : index2 === 3 ? [0, 0, -3.4] : [(index2 - 1) * 3.5, 0, 0],
        rotation: [0, 0, 0],
        scale: [1, 1, 1]
      },
      visible: true,
      renderMode: stress ? "instanced" : "standard",
      material: {}
    });
  }
  return parseScene({
    schemaVersion: "1.0.0",
    projectId: "industrial-demo",
    sceneId: stress ? "stress-lab" : "line-a",
    sceneRevision: "draft",
    name: stress ? "Synthetic instance stress lab" : "Industrial pump station",
    coordinateSystem: { kind: "local", unit: "m", upAxis: "Y", handedness: "right" },
    assets: (stress ? [valve] : [pump, valve]).map(({ assetId, assetRevision, contentHash, metadataHash }) => ({ assetId, assetRevision, contentHash, metadataHash })),
    entities,
    bookmarks: [{ id: "overview", name: "Overview", position: stress ? [58, 48, 62] : [9, 7, 12], target: [0, 0.7, 0] }],
    environment: { background: "#101c2c", ground: true }
  });
}
async function seedDemo(store2) {
  if (store2.sceneHead("line-a"))
    return;
  for (const kind of ["pump", "valve"]) {
    const fixture = await createFixture(kind);
    const job = await store2.importAsset(fixture.bytes, fixture.metadata, "bootstrap");
    while (store2.job(job.id).status === "queued")
      await store2.processNextJob();
    if (store2.job(job.id).status !== "ready")
      throw new Error(`Fixture import failed: ${JSON.stringify(store2.job(job.id).error)}`);
  }
  for (const stress of [false, true]) {
    const document2 = makeDemoDocument(store2.assets(), stress);
    const draft = store2.createScene(document2, "bootstrap");
    await store2.publish(document2.sceneId, draft.version, "bootstrap");
  }
}

